#!/usr/bin/env python3
"""Regenerate Claude capabilities from pinned LiteLLM.

Run with Python 3.11+ and rustfmt. The LiteLLM checkout must contain the vendored revision.
"""

import argparse
import json
import re
import subprocess
import tomllib
from pathlib import Path


CRATE = Path(__file__).resolve().parents[2]


def generate_claude_capabilities(model_catalog, revision):
    lines = [
        "// Generated by third_party/litellm/generate_protocol_types.py.",
        f"// Source: BerriAI/litellm {revision}, model_prices_and_context_window.json.",
        "",
        "use super::claude_reasoning::ClaudeThinking;",
        "",
        "pub(super) const CLAUDE_THINKING: &[(&str, ClaudeThinking)] = &[",
    ]
    for name, model in sorted(model_catalog.items()):
        if (
            not name.startswith("claude-")
            or model.get("litellm_provider") != "anthropic"
            or model.get("supports_reasoning") is not True
        ):
            continue
        if model.get("supports_adaptive_thinking") is True:
            supports_xhigh = model.get("supports_xhigh_reasoning_effort") is True
            always_on = model.get("thinking_always_on") is True
            explicit_disable = (
                model.get("thinking_on_by_default") is True and not always_on
            )
            profile = (
                "ClaudeThinking::Adaptive { "
                f"supports_xhigh: {str(supports_xhigh).lower()}, "
                f"disable_with_thinking_field: {str(explicit_disable).lower()}, "
                f"always_on: {str(always_on).lower()} }}"
            )
        else:
            profile = "ClaudeThinking::Legacy"
        lines.append(f"    ({json.dumps(name)}, {profile}),")
    lines.append("];")
    return "\n".join(lines) + "\n"


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("checkout", type=Path, help="local LiteLLM git checkout")
    parser.add_argument("--check", action="store_true", help="compare without writing files")
    args = parser.parse_args()
    checkout = args.checkout.resolve()
    manifest = CRATE.parent / "bamboo-litellm-llms-types" / "Cargo.toml"
    revision = tomllib.loads(manifest.read_text())["package"]["metadata"]["upstream"]["rev"]

    def read_upstream(path):
        return subprocess.check_output(
            ["git", "-C", str(checkout), "show", f"{revision}:{path}"], text=True
        )

    model_catalog = json.loads(read_upstream("model_prices_and_context_window.json"))
    path = CRATE / "src/providers/anthropic/litellm/capabilities.rs"
    generated = subprocess.run(
        ["rustfmt", "--edition", "2021", "--emit", "stdout"],
        input=generate_claude_capabilities(model_catalog, revision),
        text=True, check=True, stdout=subprocess.PIPE,
    ).stdout
    if args.check:
        if path.read_text() != generated:
            parser.error(f"{path.relative_to(CRATE)} differs from the pinned source {revision}")
    else:
        path.write_text(generated)


if __name__ == "__main__":
    main()
